// Parliamentary Procedure Practice Test 1. Original questions written for Valus from the HOSA 2026–27
// test plan (National Association of Parliamentarians topics), slightly harder than the sample items:
// applying Robert's Rules to meeting situations, vote thresholds and motion characteristics.
import {q, mix} from './q.js';
const RONR='Robert’s Rules of Order Newly Revised', BRIEF='Robert’s Rules of Order Newly Revised In Brief', NAP='NAP Study Questions';
const WHY='Why Have Rules', MEET='What Happens at a Meeting?', MOT='Handling Motions', DEB='Debate', AMD='Amendments', POST='Postponing and Referring to a Committee', MIND='How a Group Can Change Its Mind', VOTE='Voting and Elections', BYL='Bylaws and Other Rules and How to Use Them', ENF='How Rules are Enforced and Suspended', TABLE='Table of Rules', OFF='Officers, Committee Chairman, or Member';

export default {
 id:'parliamentary-procedure-1',
 event:'Parliamentary Procedure',
 title:'Practice Test 1',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Robert’s Rules of Order Newly Revised, RONR In Brief and NAP study questions',
 plan:[{area:'National Association of Parliamentarians',weight:100,topics:[WHY,MEET,MOT,DEB,AMD,POST,MIND,VOTE,BYL,ENF,TABLE,OFF]}],
 questions:mix([
  q(WHY,'Parliamentary procedure is designed to protect the rights of which groups?','Majority, minority, individuals and absentees',['Only the majority','Only the presiding officer','Only members who attend every meeting'],'B','Rules balance the majority’s right to decide with the minority’s right to be heard, individuals’ rights and the rights of absent members.',BRIEF),
  q(WHY,'If an organization’s bylaws do not set a quorum, what is the quorum under Robert’s Rules?','A majority of the entire membership',['Any number of members present','Two-thirds of the membership','Ten members'],'D','The quorum is the minimum number needed to do business. Organizations usually set a lower number in their bylaws.',RONR),
  q(WHY,'How does an organization adopt Robert’s Rules as its parliamentary authority?','By naming it in the bylaws',['By the president’s announcement','By a vote at each meeting','It applies automatically to all groups'],'A','The bylaws usually state that Robert’s Rules governs in all cases not covered by the organization’s own rules.',BRIEF),
  q(WHY,'Which basic principle limits a meeting to considering how many main motions at once?','One at a time',['Two at a time','As many as are seconded','As many as the chair allows'],'C','Only one main motion can be pending at a time, which keeps discussion focused.',BRIEF),
  q(MEET,'In the standard order of business, what usually comes first after the call to order?','Reading and approval of minutes',['New business','Unfinished business','Reports of special committees'],'B','The standard order is minutes, reports of officers and standing committees, special committee reports, special orders, unfinished business and general orders, then new business.',RONR),
  q(MEET,'What should meeting minutes mainly record?','What was done, not what was said',['Every comment made in debate','The secretary’s opinions','Only the names of those present'],'D','Minutes record actions taken, motions and results, not a word-for-word account of discussion.',BRIEF),
  q(MEET,'How does a member obtain the floor to speak?','Rises and waits to be recognized',['Speaks out whenever there is a pause','Raises a hand without waiting','Writes a note to the secretary'],'A','Only the member recognized by the chair may speak, which keeps the meeting orderly.',BRIEF),
  q(MEET,'Business that was pending when the last meeting adjourned is taken up under which heading?','Unfinished business',['New business','Announcements and good of the order','Special orders only'],'C','Items left pending or postponed to this meeting come up under unfinished business and general orders.',RONR),
  q(MOT,'After a motion is made and seconded, what must happen before the assembly can debate it?','The chair must state the question',['The secretary must read the minutes','A vote must be taken','The maker must leave the room'],'B','Once the chair states the question, the motion belongs to the assembly and can be debated.',BRIEF),
  q(MOT,'What does a second to a motion indicate?','Another member wants it discussed',['The seconder agrees with the motion','The motion has passed','The chair approves of the motion'],'D','A second shows that at least two members want the motion discussed; the seconder may still vote against it.',BRIEF),
  q(MOT,'Which type of motion has the lowest rank and can be made only when no other business is pending?','A main motion',['A privileged motion','An incidental motion','A subsidiary motion'],'A','Main motions bring business before the assembly. Other motions rank above them and can be made while they are pending.',RONR),
  q(MOT,'Which is a privileged motion?','Recess',['Amend','Postpone indefinitely','Refer to a committee'],'C','Privileged motions deal with urgent matters unrelated to pending business: fix the time to adjourn, adjourn, recess, question of privilege and call for the orders of the day.',RONR),
  q(MOT,'A member believes the rules are being broken. Which incidental motion should be used?','Point of order',['Lay on the table','Previous question (close debate)','Reconsider'],'B','A point of order asks the chair to enforce the rules. It can interrupt and needs no second.',BRIEF),
  q(DEB,'Under Robert’s Rules, unless the group adopts other rules, how many times may a member speak on the same question on the same day?','Twice',['Once','Three times','As often as the member likes'],'D','Each speech can be up to 10 minutes, and no member may speak a second time while someone who has not spoken wants the floor.',RONR),
  q(DEB,'What vote does the motion for the previous question (to close debate) require?','Two-thirds',['Majority','Unanimous consent only','One-third'],'A','Closing or limiting debate takes away members’ rights, so it requires a two-thirds vote.',RONR),
  q(DEB,'Why should the presiding officer avoid taking part in debate while presiding?','The chair must remain impartial',['The chair has no right to vote','The chair cannot understand the issue','The chair must leave the room'],'C','If the chair wants to debate, the chair steps aside and does not return to the chair until the pending question is decided.',BRIEF),
  q(DEB,'During debate, how should members address their remarks?','Through the chair, not to other members directly',['Directly to the member they disagree with','Only to the secretary','To the audience'],'B','Directing remarks through the chair keeps debate impersonal and courteous.',BRIEF),
  q(AMD,'How many levels of amendment may be pending on a main motion at one time?','Two',['One','Three','Unlimited'],'D','A primary amendment changes the main motion, and a secondary amendment changes the primary. A third level is not allowed.',RONR),
  q(AMD,'Which requirement applies to every amendment?','It must be germane to the motion it amends',['It must be longer than the motion','It must be proposed by the chair','It must reverse the motion’s intent'],'A','Germane means closely related. An amendment cannot introduce an unrelated subject.',RONR),
  q(AMD,'Which is one of the basic forms of amendment?','Strike out and insert',['Repeat and confirm','Translate into another language','Summarize the motion'],'C','The forms are to insert or add, to strike out, and to strike out and insert (including substitution).',RONR),
  q(AMD,'A main motion, a primary amendment and a secondary amendment are pending. In what order are they voted on?','Secondary, then primary, then the main motion',['Main motion, then primary, then secondary','Primary, then secondary, then main motion','All at once'],'B','Votes are taken in reverse order of their making, from the most recently made (highest-ranking) motion down.',RONR),
  q(POST,'Which motion delays a main motion until a specific later time or meeting?','Postpone to a certain time',['Postpone indefinitely','Lay on the table','Adjourn'],'D','Postponing definitely sets a time for the motion to come up again. Postpone indefinitely effectively kills the motion.',RONR),
  q(POST,'Which motion sends a pending question to a smaller group for study?','Commit or refer',['Reconsider','Rescind','Division of the assembly'],'A','The motion to refer can specify the committee, its instructions and when it should report.',BRIEF),
  q(POST,'What is the proper use of the motion to lay on the table?','To set it aside for urgent business',['To kill a motion permanently','To close debate immediately','To end the meeting right away'],'C','Using it to kill a motion is improper. A motion laid on the table can be taken from the table later.',RONR),
  q(POST,'Which motion brings back a motion that was laid on the table?','Take from the table',['Reconsider','Postpone indefinitely','Commit to a committee'],'B','Take from the table is not debatable and requires a majority vote.',RONR),
  q(MIND,'Who may make the motion to reconsider a vote?','A member who voted on the prevailing side',['Any member, regardless of how they voted','Only the chair','Only absent members'],'D','This prevents the losing side from simply repeating the debate. It must be made the same day as the vote or the next day of a session.',RONR),
  q(MIND,'What vote is needed to rescind a motion when no previous notice has been given?','Two-thirds of the votes cast',['A simple majority of those voting','Unanimous consent only','One-third'],'A','With previous notice, a majority vote is enough. Without notice, a two-thirds vote or a majority of the entire membership is required.',RONR),
  q(MIND,'An assembly wants to change the wording of a motion it adopted at an earlier meeting. Which motion is used?','Amend a prior action',['Amend the pending motion','Reconsider','Lay on the table'],'C','It has the same vote requirements as rescind: a majority with previous notice, or two-thirds (or a majority of the entire membership) without it.',RONR),
  q(MIND,'A committee is studying a matter, but the assembly wants to take it back. Which motion is used?','Discharge a committee',['Commit','Previous question','Recess'],'B','Discharging a committee usually needs a two-thirds vote or a majority with previous notice, unless the committee has failed to report on time.',RONR),
  q(VOTE,'Under Robert’s Rules, what is a majority vote?','More than half of the votes cast',['More than half of the members present','Half of the votes cast','The most votes of any candidate'],'D','Blanks and abstentions do not count. Bylaws can require a different basis, such as a majority of members present.',RONR),
  q(VOTE,'If 60 votes are cast on a motion requiring a two-thirds vote, how many affirmative votes are needed?','40',['30','31','45'],'A','Two-thirds of 60 is 40, so at least 40 members must vote yes. Abstentions and blanks are not counted as votes cast.',RONR),
  q(VOTE,'A member doubts the result of a voice vote. What can the member call for?','Division of the assembly',['Point of information','Recess','Adjourn'],'C','A division requires a rising (standing) vote so the result can be seen. Any member can demand it.',BRIEF),
  q(VOTE,'Which voting method is usually used for elections because it keeps votes secret?','Ballot',['Voice vote','Show of hands','Unanimous consent of members present'],'B','Ballots protect members from pressure. Bylaws often require ballot elections.',BRIEF),
  q(VOTE,'In an election with three candidates, one receives 40% of the votes and no one has a majority. Under Robert’s Rules, what happens?','Balloting continues until a majority',['The candidate with 40% is elected','The president chooses the winner','The office stays empty for a year'],'D','A plurality does not elect unless the bylaws specifically allow it.',RONR),
  q(BYL,'What vote is usually required to amend bylaws when no specific provision exists?','Previous notice and a two-thirds vote',['A simple majority with no notice','Unanimous consent','The president’s approval only'],'A','Bylaws are fundamental documents, so changing them requires notice and a higher vote.',RONR),
  q(BYL,'Which document has the highest authority over an organization?','Applicable law',['Standing rules','Special rules of order','Bylaws'],'C','The ranking is law, the corporate charter, bylaws, special rules of order, then standing rules and the parliamentary authority.',RONR),
  q(BYL,'Which rules deal with administrative details, such as meeting times, and can be adopted by a majority vote?','Standing rules',['Bylaws','Corporate charter','Federal laws'],'B','Standing rules handle administrative matters and can usually be adopted or amended by a majority.',RONR),
  q(BYL,'Can an organization’s bylaws be suspended by a vote of the members?','No, unless the bylaw allows it',['Yes, by a majority vote','Yes, by the president alone','Yes, at any special meeting'],'D','Bylaws cannot be suspended, except for provisions that are rules of order or that specifically allow suspension.',RONR),
  q(ENF,'When must a point of order generally be raised?','At the time the breach occurs',['At the next meeting','Only after the meeting adjourns','Within one week'],'A','A point of order must usually be timely; some continuing breaches, such as violations of bylaws, can be raised later.',RONR),
  q(ENF,'A member disagrees with the chair’s ruling on a point of order. Which motion lets the assembly decide?','Appeal',['Reconsider','Rescind','Postpone indefinitely'],'C','An appeal must be made immediately and needs a second. A majority or tie vote sustains the chair.',RONR),
  q(ENF,'What vote does the motion to suspend the rules usually require?','Two-thirds',['Majority','Unanimous only','One-third'],'B','Suspending rules of order affects members’ rights, so it requires a two-thirds vote.',RONR),
  q(ENF,'Which rules cannot be suspended, even by unanimous consent?','Rules that protect absent members',['Rules about meeting times','Rules about the order of business','Rules about the length of speeches'],'D','Rules protecting absentees, individual basic rights or required by law cannot be suspended.',RONR),
  q(TABLE,'Which motion is not debatable?','Lay on the table',['Main motion','Postpone indefinitely','Amend a debatable motion'],'A','Undebatable motions, such as lay on the table and previous question, help the assembly move quickly.',RONR),
  q(TABLE,'Which motion does not require a second?','Point of order',['Main motion','Adjourn','Commit'],'C','Point of order, parliamentary inquiry and request for information are handled by the chair without a second.',RONR),
  q(TABLE,'Which motion can interrupt a member who has the floor?','Raise a question of privilege',['Main motion','Commit','Postpone to a certain time'],'B','Urgent matters, such as a question of privilege or a point of order, can interrupt a speaker.',RONR),
  q(TABLE,'Which motion requires a two-thirds vote?','Limit or extend limits of debate',['Adjourn','Recess','Postpone to a certain time'],'D','Motions that limit members’ rights, such as limiting debate or closing it, require two-thirds.',RONR),
  q(OFF,'Who presides at meetings when the president is absent?','The vice-president',['The secretary','The treasurer','The newest member'],'A','The vice-president presides in the president’s absence and may fill a vacancy in the presidency if the bylaws provide.',BRIEF),
  q(OFF,'How is a treasurer’s report normally handled at a meeting?','It is received and placed on file without a vote',['It is adopted by a two-thirds vote','It is debated and amended','It is ignored until the end of the year'],'C','The report is for information. Only an auditor’s report on the accounts is adopted.',RONR),
  q(OFF,'What does it mean for a member to serve on a board “ex officio”?','They serve because of another office',['The member cannot vote','The member is temporary','The member was elected by ballot'],'B','Ex officio means “by virtue of office.” An ex officio member generally has full rights, including voting, unless the bylaws say otherwise.',RONR),
  q(OFF,'Which officer is responsible for keeping the minutes and official records?','Secretary',['President','Vice-president','Parliamentarian'],'D','The secretary records minutes and keeps records. The parliamentarian advises the chair but does not make rulings.',BRIEF)
 ],179)
};
